import * as React from 'react';
import Button from '@mui/material/Button';
import Dialog from '@mui/material/Dialog';
import DialogActions from '@mui/material/DialogActions';
import DialogContent from '@mui/material/DialogContent';
import DialogTitle from '@mui/material/DialogTitle';
import {
  Box,
  CircularProgress,
  Grid,
  Stack,
  TextField,
  Typography,
  useMediaQuery,
} from '@mui/material';
import PaymentsOutlinedIcon from '@mui/icons-material/PaymentsOutlined';
import FieldHeader from '../../../components/FieldHeader';
import { theme } from '../../../theme';
import { useFormik } from 'formik';
import { useSupplierpayCreditMutation } from '../../posApi';
import { useNotifier } from '../../../core/Notifier';
import { appColors, HEADER_GRADIENT } from '../../../theme/appColors';
import { useTranslation } from 'react-i18next';
import CreditCardIcon from '@mui/icons-material/CreditCard';
import PaymentsIcon from '@mui/icons-material/Payments';
import ReceiptIcon from '@mui/icons-material/Receipt';
import { ISupplierDetailsData } from '../../../core/Interface/supplier.interface';

interface INewSupplier {
  openModel?: boolean;
  title: string;
  handleCloseDialog: (close: boolean) => void;
  data?: ISupplierDetailsData;
}

const NewSupplier = ({
  title,
  openModel = false,
  handleCloseDialog,
  data,
}: INewSupplier) => {
  const [open] = React.useState(openModel);
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const [newSupplier, { isLoading }] = useSupplierpayCreditMutation();
  const { showErrorMessage, showMessage } = useNotifier();
  const { t } = useTranslation(['common', 'category', 'suppliermanage']);
  const buttonText = data ? t('suppliermanage:title.pay') : t('common:create');
  const [paymentMethod, setPaymentMethod] = React.useState('Cash');

  const handleClose = () => {
    handleCloseDialog(false);
  };

  const formik = useFormik({
    initialValues: {
      purchaseId: data?.id,
      amount: '',
      paymentMethod: 'Cash',
    },
    onSubmit: async (values) => {
      try {
        const temData = {
          purchaseId: values.purchaseId,
          amount: values.amount,
          paymentMethod: values.paymentMethod,
        };
        if (!data) {
          delete values.purchaseId;
        }

        const addSupplierResponse = await newSupplier(temData).unwrap();
        if (!addSupplierResponse.status) {
          showErrorMessage(addSupplierResponse.message);
        } else {
          showMessage(addSupplierResponse.message);
          handleClose();
        }
      } catch (error) {
        showErrorMessage((error as Error).message);
      }
    },
  });

  const handleCardClick = (method: string) => {
    setPaymentMethod(method);
    formik.setFieldValue('paymentMethod', method);
  };

  return (
    <div>
      <form noValidate onSubmit={formik.handleSubmit}>
        <Dialog
          aria-describedby="alert-dialog-description"
          classes={{ paper: 'inherit' }}
          fullScreen={isMobile}
          fullWidth={isMobile}
          maxWidth="lg"
          open={open}
        >
          <DialogTitle
            sx={{
              fontWeight: 600,
              p: 3,
              backgroundColor: appColors.blueGreyishLight[30],
              borderRadius: '5px',
            }}
          >
            {title}
          </DialogTitle>
          <DialogContent
            sx={{ width: isMobile ? 'auto' : '40vw', p: 4, marginTop: '20px' }}
          >
            <Grid
              container
              justifyContent="space-between"
              mb={3}
            >
              <Grid
                item
                lg={3.7}
                md={3.8}
                onClick={() => handleCardClick('Cash')}
                sm={3.9}
                xs={3.9}
                {...formik.getFieldProps('paymentMethod')}
                sx={{
                  border: '2px solid #E6E8F3',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  flexDirection: 'column',
                  borderRadius: 2,
                  backgroundColor:
                    paymentMethod === 'Cash'
                      ? appColors.reflexBlue[10]
                      : 'transparent',
                  '&:hover': {
                    backgroundColor: appColors.reflexBlue[10],
                    cursor: 'pointer',
                  },
                }}
              >
                <PaymentsIcon style={{ width: 50, height: 50 }} />
                <Typography sx={{ fontWeight: 500, fontSize: '1.2rem' }}>
                  Cash
                </Typography>
              </Grid>{' '}
              <Grid
                item
                lg={3.7}
                md={3.8}
                onClick={() => handleCardClick('Card')}
                sm={3.9}
                xs={3.9}
                {...formik.getFieldProps('paymentMethod')}
                sx={{
                  border: '2px solid #E6E8F3',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  flexDirection: 'column',
                  borderRadius: 2,
                  backgroundColor:
                    paymentMethod === 'Card'
                      ? appColors.reflexBlue[10]
                      : 'transparent',
                  '&:hover': {
                    backgroundColor: appColors.reflexBlue[10],
                    cursor: 'pointer',
                  },
                }}
              >
                <CreditCardIcon style={{ width: 50, height: 50 }} />
                <Typography sx={{ fontWeight: 500, fontSize: '1.2rem' }}>
                  Card
                </Typography>
              </Grid>
              <Grid
                item
                lg={3.7}
                md={3.8}
                onClick={() => handleCardClick('Cheque')}
                sm={3.9}
                xs={3.9}
                {...formik.getFieldProps('paymentMethod')}
                sx={{
                  py: 1,
                  border: '2px solid #E6E8F3',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  flexDirection: 'column',
                  borderRadius: 2,
                  backgroundColor:
                    paymentMethod === 'Cheque'
                      ? appColors.reflexBlue[10]
                      : 'transparent',
                  '&:hover': {
                    backgroundColor: appColors.reflexBlue[10],
                    cursor: 'pointer',
                  },
                }}
              >
                <ReceiptIcon style={{ width: 50, height: 50 }} />
                <Typography sx={{ fontWeight: 500, fontSize: '1.2rem' }}>
                  Cheque
                </Typography>
              </Grid>
            </Grid>
            <Grid container>
              <GridItem>
                <FieldHeader title="Amount" />
                <TextField
                  autoComplete="off"
                  placeholder="Amount"
                  size="small"
                  {...formik.getFieldProps('amount')}
                  sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                />
              </GridItem>
            </Grid>
          </DialogContent>
          <DialogActions sx={{ paddingRight: '24px', p: 4, py: 3, gap: 2 }}>
            <Button
              onClick={handleClose}
              sx={{
                width: 200,
                height: 42,
                borderRadius: '5px',
              }}
              variant="outlined"
            >
              {t('common:cancel')}
            </Button>
            <Button
              autoFocus
              onClick={() => {
                formik.handleSubmit();
              }}
              sx={{
                width: 200,
                height: 42,
                borderRadius: '5px',
              }}
              type="submit"
              variant="contained"
            >
              {isLoading && (
                <Box sx={{ pr: 2, pt: 0.5 }}>
                  <CircularProgress
                    size={16}
                    sx={{ color: 'white' }}
                  />
                </Box>
              )}
              {buttonText}
            </Button>
          </DialogActions>
        </Dialog>
      </form>
    </div>
  );
};

export default React.memo(NewSupplier);

// eslint-disable-next-line react/no-multi-comp
const GridItem = ({ ...rest }) => {
  return (
    <Grid
      item
      key={1}
      lg={12}
      sm={12}
      xs={12}
      {...rest}
    />
  );
};
